/**
 * Info Endpoints
 * 
 * Additional endpoints needed by the frontend
 */

import { Request, Response } from 'express';
import { AuthenticatedRequest } from './middleware.js';
import type { FilesystemManager } from '../storage/filesystem.js';
import { Server as SocketIOServer } from 'socket.io';
import { broadcastFileChange, broadcastItemAdded } from '../websocket/events.js';
import { logger, createLogger } from '../utils/logger.js';
const log = createLogger('api-info');
import path from 'path';
import { existsSync, readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname } from 'path';
import { getBaseUrl } from '../utils/urlUtils.js';

// getBaseUrl is imported from ../utils/urlUtils.js - handles Active Proxy correctly

/**
 * Ordered list of icon filenames to probe inside an installed app's bundle
 * when its manifest doesn't declare one. We try high-quality PNG logos
 * first (what most modern PWA-style dApp bundles ship), then Android /
 * Apple touch icons, then generic icon.* names, and finally fall back to
 * favicon.ico (usually a 16×16 .ico that renders pixelated at 48 px —
 * only used as a last resort). See DAPP-UX-POLISH-V12 #3 — Glide
 * Finance's bundle ships `logo.png` etc. but the previous list only
 * matched `favicon.ico`, which looked broken in the dApp Centre.
 */
const BUNDLE_ICON_CANDIDATES = [
  'logo.png',
  'logo_256x256.png',
  'logo_200x200.png',
  'logo_128x128.png',
  'icon-512.png',
  'icon-256.png',
  'icon-192.png',
  'android-chrome-512x512.png',
  'android-chrome-192x192.png',
  'apple-touch-icon.png',
  'apple-touch-icon-precomposed.png',
  'favicon-192.png',
  'favicon-64.png',
  'favicon.png',
  'icon.png',
  'icon.svg',
  'favicon.ico',
];

/**
 * Resolve a bundle-relative icon URL for an installed app.
 *
 * Strategy:
 *   1. If the bundle ships a PWA web manifest (`manifest.json` or
 *      `manifest.webmanifest`) with an `icons` array, pick the entry
 *      whose `sizes` parses to the largest square — that's what the
 *      author intended for app-icon surfaces.
 *   2. Otherwise probe `BUNDLE_ICON_CANDIDATES` in order and return
 *      the first that exists on disk.
 *
 * Returns `undefined` if nothing usable was found, in which case the
 * caller should either leave the icon blank or fall back to a hardcoded
 * SVG. Never throws — I/O errors are swallowed.
 */
function resolveBundleIcon(
  installedAppsDir: string,
  appName: string,
  baseUrl: string
): string | undefined {
  const appDir = path.join(installedAppsDir, appName);
  try {
    // Step 1: try PWA web manifest.
    const webManifestNames = ['manifest.json', 'manifest.webmanifest'];
    for (const name of webManifestNames) {
      const p = path.join(appDir, name);
      if (!existsSync(p)) continue;
      try {
        const raw = readFileSync(p, 'utf8');
        const json = JSON.parse(raw);
        const icons = Array.isArray(json?.icons) ? json.icons : [];
        if (icons.length === 0) continue;
        // Parse "NxM" strings; prefer the largest square.
        const scored = icons
          .map((ic: any) => {
            if (!ic?.src) return { score: -1, src: null };
            const size = typeof ic.sizes === 'string'
              ? parseInt((ic.sizes.split(' ')[0] || '0').split('x')[0], 10)
              : 0;
            return { score: Number.isFinite(size) ? size : 0, src: ic.src };
          })
          .filter((x: { src: string | null }) => !!x.src)
          .sort((a: { score: number }, b: { score: number }) => b.score - a.score);
        if (scored.length > 0 && scored[0].src) {
          const rel = scored[0].src.replace(/^\/+/, '');
          // Only accept paths that actually exist on disk to avoid 404s.
          if (existsSync(path.join(appDir, rel))) {
            return `${baseUrl}/installed-apps/${appName}/${rel}`;
          }
        }
      } catch {
        // malformed JSON — fall through to filename probes.
      }
    }

    // Step 2: filename probes.
    for (const candidate of BUNDLE_ICON_CANDIDATES) {
      if (existsSync(path.join(appDir, candidate))) {
        return `${baseUrl}/installed-apps/${appName}/${candidate}`;
      }
    }
  } catch {
    // Any unexpected disk error — just give up rather than 500 the app list.
  }
  return undefined;
}

/**
 * Get API info
 * GET /api/info
 */
export function handleAPIInfo(req: Request, res: Response): void {
  res.json({
    version: '2.5.1',
    server: 'pc2-node',
    features: {
      file_storage: true,
      real_time: true,
      authentication: true
    }
  });
}

/**
 * Get launch apps
 * GET /get-launch-apps
 * Returns apps available in the start menu
 * Optionally authenticated - if auth token provided, returns user's recent apps
 */
export function handleGetLaunchApps(req: Request, res: Response): void {
  const iconSize = parseInt(req.query.icon_size as string) || 64;
  const bosonService = req.app?.locals?.bosonService;
  const baseUrl = getBaseUrl(req, bosonService);
  const db = (req.app.locals.db as any);
  
  // Helper function to load SVG icon as base64
  // ALWAYS uses hardcoded base64 icons for 100% isolation - no file system dependencies
  const loadIconAsBase64 = (appName: string): string | undefined => {
    try {
      // Hardcoded base64 icons (matching mock server)
      // This ensures 100% isolation - no external dependencies
      const hardcodedIcons: Record<string, string> = {
        // Text Editor - notepad with pencil design (rounded)
        'editor': 'data:image/svg+xml;base64,',
        // Image Viewer - landscape with sun (rounded)
        'viewer': 'data:image/svg+xml;base64,',
        'player': 'data:image/svg+xml;base64,',
        'pdf': 'data:image/svg+xml;base64,',
        // Camera - professional camera with lens (rounded)
        'camera': 'data:image/svg+xml;base64,',
        // dApp Centre - grid of colorful apps (rounded)
        'app-center': 'data:image/png;base64,',
        // Recorder - microphone with sound waves (rounded, centered)
        'recorder': 'data:image/svg+xml;base64,',
        // Solitaire - stacked playing cards with heart (rounded, centered)
        'solitaire-frvr': 'data:image/svg+xml;base64,',
        'terminal': 'data:image/svg+xml;base64,',
        'system-terminal': 'data:image/svg+xml;base64,',
        // Calculator - professional calculator design (rounded)
        'calculator': 'data:image/svg+xml;base64,',
        // File Analyzer - document with text lines (rounded)
        'file-processor': 'data:image/svg+xml;base64,',
        // AI Chat - Flint AI (stylized obsidian flake on dark background)
        'ai-chat': 'data:image/png;base64,',
        // DAO Dashboard - official Elastos DAO logo (dark bg, teal chevrons)
        'dao-dashboard': 'data:image/png;base64,'
      };
      
      // Return hardcoded icon if available
      if (hardcodedIcons[appName]) {
        return hardcodedIcons[appName];
      }
      
      // Icon not found
      return undefined;
    } catch (error) {
      logger.warn(`[get-launch-apps] Error loading icon for ${appName}:`, error);
      return undefined;
    }
  };
  
  // Define available apps (these match the apps in src/backend/apps/)
  const apps: Record<string, any>[] = [
    {
      name: 'editor',
      title: 'Text Editor',
      uuid: 'app-editor',
      icon: loadIconAsBase64('editor'),
      description: 'Code and text editor with syntax highlighting'
    },
    {
      name: 'viewer',
      title: 'Image Viewer',
      uuid: 'app-viewer',
      icon: loadIconAsBase64('viewer'),
      description: 'View and edit images'
    },
    // Legacy `player` (basic browser HTML5 audio/video) removed in v1.2 — replaced
    // by `elacity-player` capsule (auto-installed at boot via test-apps sync).
    // Keeping the comment as a tombstone so we don't accidentally re-add it.
    {
      name: 'camera',
      title: 'Camera',
      uuid: 'app-camera',
      icon: loadIconAsBase64('camera'),
      description: 'Take photos and videos'
    },
    {
      name: 'app-center',
      title: 'dApp Centre',
      uuid: 'app-app-center',
      icon: loadIconAsBase64('app-center'),
      description: 'Browse and install dApps'
    },
    {
      name: 'pdf',
      title: 'PDF',
      uuid: 'app-pdf',
      icon: loadIconAsBase64('pdf'),
      description: 'View PDF documents'
    },
    {
      name: 'system-terminal',
      title: 'Terminal',
      uuid: 'app-system-terminal',
      icon: loadIconAsBase64('terminal'),
      description: 'Real shell access to your PC2 node',
      pc2_exclusive: true
    },
    {
      name: 'recorder',
      title: 'Recorder',
      uuid: 'app-recorder',
      icon: loadIconAsBase64('recorder'),
      description: 'Record screen and audio'
    },
    {
      name: 'solitaire-frvr',
      title: 'Solitaire FRVR',
      uuid: 'app-solitaire-frvr',
      icon: loadIconAsBase64('solitaire-frvr'),
      description: 'Play Solitaire card game (third-party; may show consent/ads)'
    },
    {
      name: 'calculator',
      title: 'WASM Calculator',
      uuid: 'app-calculator',
      icon: loadIconAsBase64('calculator'),
      description: 'Calculator powered by WASMER runtime',
      index_url: `${baseUrl}/apps/calculator/index.html`
    },
    {
      name: 'file-processor',
      title: 'File Analyzer',
      uuid: 'app-file-processor',
      icon: loadIconAsBase64('file-processor'),
      description: 'Analyze text files - word, line, and character counts',
      index_url: `${baseUrl}/apps/file-processor/index.html`
    },
    {
      name: 'ai-chat',
      title: 'AI Chat',
      uuid: 'app-ai-chat',
      icon: loadIconAsBase64('ai-chat'),
      description: 'Personal AI assistant with file management',
      pc2_exclusive: true
    },
    {
      name: 'dao-dashboard',
      title: 'Elastos DAO',
      uuid: 'app-dao-dashboard',
      icon: loadIconAsBase64('dao-dashboard'),
      description: 'Elastos DAO governance - proposals, council, voting',
      index_url: `${baseUrl}/apps/dao-dashboard/index.html`,
      pc2_exclusive: true,
      maximize_on_start: true
    }
  ];

  // Mark all hardcoded apps above as system apps so the dApp Centre can
  // classify them authoritatively instead of inferring via the inverse of
  // /api/installed-apps (which is fragile on auth hiccups — see
  // .cursor/tasks/DAPP-CENTRE-BUILTIN-CLASSIFICATION).
  // User-installed apps pushed below carry isSystem: false.
  for (const a of apps) {
    a.isSystem = true;
  }

  // Merge installed apps from dApp Store
  const appInstallService = req.app?.locals?.appInstallService;
  if (appInstallService) {
    try {
      const installedApps = appInstallService.list();
      const installedAppsDir = appInstallService.getAppsDir();
      for (const installed of installedApps) {
        const manifest = JSON.parse(installed.manifest_json);
        if (manifest.hidden) continue;
        let iconUrl: string | undefined;
        if (manifest.iconDataUrl) {
          iconUrl = manifest.iconDataUrl;
        } else if (installed.icon && installed.icon.startsWith('data:')) {
          // Some bundles store the data URL directly in the `icon` field.
          iconUrl = installed.icon;
        } else if (installed.icon) {
          iconUrl = `${baseUrl}/installed-apps/${installed.app_name}/${installed.icon}`;
        } else {
          // Manifest declared no icon: ask the shared resolver to probe
          // the install dir (PWA web manifest first, then common logo
          // filenames, finally favicon.ico). See resolveBundleIcon.
          iconUrl = resolveBundleIcon(
            installedAppsDir,
            installed.app_name,
            baseUrl
          );
        }
        apps.push({
          name: installed.app_name,
          title: installed.title,
          uuid: `app-${installed.app_name}`,
          icon: iconUrl,
          description: installed.description || '',
          index_url: `${baseUrl}/apps/${installed.app_name}/${manifest.entry || 'index.html'}`,
          installed: true,
          isSystem: false,
          version: installed.version,
          author: installed.author || undefined,
        });
      }
    } catch (err: any) {
      logger.warn('[GetLaunchApps] Failed to load installed apps:', err.message);
    }
  }

  // ──────────────────────────────────────────────────────────────────
  // Start Menu ordering
  // ──────────────────────────────────────────────────────────────────
  // The Puter Start Menu renders `recommended` in array order (see
  // src/gui/src/UI/UITaskbar.js loop at line ~227). The dApp Centre
  // similarly preserves order in its catalog grid. We promote the
  // user-facing dApp capsules to the top and let the system tools
  // (Editor, Image Viewer, Terminal, Calculator, …) follow in their
  // existing order. Non-priority apps keep their relative position
  // via a stable sort.
  const START_MENU_PRIORITY: readonly string[] = [
    'ai-chat',
    'dao-dashboard',
    'app-center',      // "dApp Centre" — sits next to the DAO so users
                       // immediately see the place to discover & install more apps.
    'elacity-market',
    'elacity-creator',
    'elacity-player',
    'ddrm-viewer',     // "Elacity Viewer"
    'elastos-nft',
    'glide-finance',
  ];
  const priorityIndex = (name: string): number => {
    const i = START_MENU_PRIORITY.indexOf(name);
    return i === -1 ? Number.MAX_SAFE_INTEGER : i;
  };
  apps
    .map((a, i) => ({ a, i, p: priorityIndex(a.name) }))
    .sort((x, y) => (x.p - y.p) || (x.i - y.i))
    .forEach((rec, idx) => { (apps as any)[idx] = rec.a; });

  // Build map for quick app lookup by name
  const appMap: Record<string, any> = {};
  for (const app of apps) {
    appMap[app.name] = app;
  }
  
  // Try to get recent apps for authenticated user
  let recentApps: any[] = [];
  
  if (db) {
    // Try to extract and validate auth token
    const authHeader = req.headers.authorization;
    let token: string | null = null;
    
    if (authHeader?.startsWith('Bearer ')) {
      token = authHeader.substring(7).trim();
      if (token.includes(',')) {
        token = token.split(',')[0].trim();
      }
    } else if (req.query.token) {
      token = String(req.query.token).trim();
    } else if (req.query.auth_token) {
      token = String(req.query.auth_token).trim();
    }
    
    if (token) {
      try {
        // SEC-3c (2026-04 audit): the previous implementation also accepted
        // `token-0x{wallet}-...` tokens here and resolved them via
        // db.getSessionByWallet(walletAddress) — an unauthenticated wallet-
        // inference primitive identical to the one removed from the auth
        // middleware. Branch removed; only real session tokens are honoured.
        const session = db.getSession(token);

        if (session?.wallet_address) {
          // Get recent app names from database
          const recentAppNames = db.getRecentApps(session.wallet_address, 10);
          
          // Map app names to full app objects with icons
          for (const appName of recentAppNames) {
            if (appMap[appName]) {
              recentApps.push(appMap[appName]);
            } else {
              // App not in predefined list, create minimal entry with icon
              recentApps.push({
                name: appName,
                title: appName.charAt(0).toUpperCase() + appName.slice(1).replace(/-/g, ' '),
                uuid: `app-${appName}`,
                icon: loadIconAsBase64(appName),
                description: ''
              });
            }
          }
          
          logger.info('[GetLaunchApps] Returning recent apps for user', {
            wallet: session.wallet_address.substring(0, 10),
            recentCount: recentApps.length
          });
        }
      } catch (error: any) {
        // Don't fail, just return empty recent apps
        logger.warn('[GetLaunchApps] Failed to get recent apps:', error.message);
      }
    }
  }
  
  // Return apps in the format expected by the frontend
  // Frontend expects: { recommended: [...], recent: [...] }
  res.json({
    recommended: apps,
    recent: recentApps
  });
}

/**
 * Disk free space (df)
 * GET /df
 */
export function handleDF(req: AuthenticatedRequest, res: Response): void {
  const filesystem = (req.app.locals.filesystem as any);
  
  // Return mock disk space info
  res.json({
    total: 10 * 1024 * 1024 * 1024, // 10GB
    used: 0,
    available: 10 * 1024 * 1024 * 1024,
    percentage: 0
  });
}

/**
 * Batch operations
 * POST /batch
 */
/**
 * Batch operations endpoint
 * POST /batch
 * Handles batch file uploads (multipart/form-data or JSON)
 * 
 * The Puter SDK's fs.upload() sends files to this endpoint
 * Format can be:
 * 1. multipart/form-data with files
 * 2. JSON with operations array
 */
export async function handleBatch(req: AuthenticatedRequest, res: Response): Promise<void> {
  const filesystem = (req.app.locals.filesystem as FilesystemManager | undefined);
  const io = (req.app.locals.io as SocketIOServer | undefined);
  
  logger.info('[Batch] Request received', {
    contentType: req.headers['content-type'],
    hasFilesystem: !!filesystem,
    wallet: req.user?.wallet_address
  });
  
  if (!req.user) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  if (!filesystem) {
    logger.warn('[Batch] Filesystem not available - IPFS not initialized');
    res.status(500).json({ 
      error: 'Filesystem not available',
      message: 'IPFS is not initialized. File uploads require IPFS to be running.'
    });
    return;
  }

  try {
    const contentType = req.headers['content-type'] || '';
    const results: any[] = [];
    
    // Check if this is multipart/form-data (files uploaded via drag-drop)
    if (contentType.includes('multipart/form-data')) {
      // Multer middleware should have parsed this
      // Files should be in req.files (if using multer) or req.body
      const files = (req as any).files || [];
      const formData = req.body || {};
      
      // Parse operation field (can be JSON string or array of JSON strings) - matching mock server logic
      let operations: any[] = [];
      if (formData.operation) {
        if (typeof formData.operation === 'string') {
          try {
            operations = JSON.parse(formData.operation);
            if (!Array.isArray(operations)) {
              operations = [operations];
            }
          } catch (e) {
            logger.warn('[Batch] Failed to parse operation:', e instanceof Error ? e.message : 'Unknown error');
          }
        } else if (Array.isArray(formData.operation)) {
          operations = formData.operation.map((op: any) => {
            if (typeof op === 'string') {
              try {
                return JSON.parse(op);
              } catch {
                return op;
              }
            }
            return op;
          });
        }
      }
      
      // Parse fileinfo if it's a JSON string - matching mock server logic
      let fileinfo: any = null;
      if (formData.fileinfo) {
        if (typeof formData.fileinfo === 'string') {
          try {
            fileinfo = JSON.parse(formData.fileinfo);
          } catch (e) {
            logger.warn('[Batch] Failed to parse fileinfo:', e instanceof Error ? e.message : 'Unknown error');
          }
        } else if (typeof formData.fileinfo === 'object') {
          fileinfo = formData.fileinfo;
        }
      }
      
      // Convert ~ paths in operations (matching mock server behavior)
      if (req.user.wallet_address && operations.length > 0) {
        for (let i = 0; i < operations.length; i++) {
          if (operations[i].path && typeof operations[i].path === 'string' && operations[i].path.startsWith('~/')) {
            operations[i].path = operations[i].path.replace('~/', `/${req.user.wallet_address}/`);
            logger.info(`[Batch] Converted operation[${i}].path: ${operations[i].path}`);
          }
        }
      }
      
      logger.info('[Batch] Processing multipart upload', {
        filesCount: Array.isArray(files) ? files.length : (files ? 1 : 0),
        formFields: Object.keys(formData),
        operationsCount: operations.length,
        hasFileinfo: !!fileinfo
      });
      
      // Handle file uploads from req.files (multer format)
      if (Array.isArray(files) && files.length > 0) {
        for (const file of files) {
          try {
            // Determine target path from operation, fileinfo, or form data (matching mock server logic)
            let destPath: string | undefined;
            
            if (operations.length > 0 && operations[0].path) {
              destPath = operations[0].path;
            } else if (fileinfo && fileinfo.path) {
              destPath = fileinfo.path;
            } else if (fileinfo && fileinfo.parent) {
              destPath = fileinfo.parent;
            } else {
              destPath = formData.path || formData.dest_path || formData.destination || req.query.path as string;
            }
            
            if (!destPath) {
              logger.error('[Batch] Missing destination path', {
                formDataKeys: Object.keys(formData),
                fileinfo,
                operations,
                filename: file.originalname || file.name
              });
              results.push({
                success: false,
                error: 'Missing destination path',
                filename: file.originalname || file.name
              });
              continue;
            }
            
            // Handle ~ home directory (fallback if not already converted in operations)
            if (destPath.startsWith('~/')) {
              destPath = destPath.replace('~/', `/${req.user.wallet_address}/`);
            } else if (destPath.startsWith('~')) {
              destPath = destPath.replace('~', `/${req.user.wallet_address}`);
            } else if (!destPath.startsWith('/')) {
              // Relative path - default to Desktop for drag-drop uploads
              destPath = `/${req.user.wallet_address}/Desktop/${destPath}`;
            }
            
            // Construct full file path
            const fileName = file.originalname || file.name || 'untitled';
            let filePath = destPath.endsWith('/') 
              ? `${destPath}${fileName}`
              : `${destPath}/${fileName}`;
            
            // Normalize the path (remove double slashes, etc.)
            filePath = filePath.replace(/\/+/g, '/');
            
            // Get file content - buffer (memoryStorage), data, or disk path (diskStorage)
            const fileContent = file.buffer || file.data;
            const onDisk = !fileContent && file.path;
            const reportedSize = file.size || (fileContent ? fileContent.length : 0);
            const actualSize = fileContent ? (Buffer.isBuffer(fileContent) ? fileContent.length : (fileContent instanceof Uint8Array ? fileContent.length : Buffer.byteLength(fileContent))) : reportedSize;
            
            logger.info('[Batch] Uploading file', {
              originalDest: formData.path || formData.dest_path || formData.fileinfo || formData.operation || req.query.path,
              resolvedDest: destPath,
              fileName,
              filePath,
              reportedSize,
              actualSize,
              hasBuffer: !!file.buffer,
              hasData: !!file.data,
              onDisk,
              mimeType: file.mimetype || file.type
            });
            
            if (!fileContent && !onDisk) {
              logger.error('[Batch] No file content received', {
                fileName,
                hasBuffer: !!file.buffer,
                hasData: !!file.data,
                fileKeys: Object.keys(file)
              });
              results.push({
                success: false,
                error: 'No file content received',
                filename: fileName
              });
              continue;
            }
            
            // Write file to filesystem -- stream from disk for large files
            const metadata = onDisk
              ? await filesystem.writeFileFromPath(
                  filePath,
                  file.path,
                  req.user.wallet_address,
                  { mimeType: file.mimetype || file.type }
                )
              : await filesystem.writeFile(
                  filePath,
                  fileContent,
                  req.user.wallet_address,
                  { mimeType: file.mimetype || file.type }
                );
            
            // Extract parent directory path (dirpath) - CRITICAL for frontend
            const pathParts = metadata.path.split('/').filter(p => p);
            pathParts.pop(); // Remove filename
            const dirpath = pathParts.length > 0 ? '/' + pathParts.join('/') : '/';
            
            const fileUid = `uuid-${metadata.path.replace(/\//g, '-')}`;
            
            results.push({
              success: true,
              path: metadata.path,
              result: {
                path: metadata.path,
                name: metadata.path.split('/').pop() || 'untitled',
                size: metadata.size,
                mime_type: metadata.mime_type
              }
            });
            
            // Broadcast item.added event (frontend listens for this, not file:changed)
            if (io) {
              broadcastItemAdded(io, req.user.wallet_address, {
                uid: fileUid,
                uuid: fileUid,
                name: metadata.path.split('/').pop() || 'untitled',
                path: metadata.path,
                dirpath: dirpath, // CRITICAL: Frontend uses this to find where to add the item
                size: metadata.size,
                type: metadata.mime_type || null,
                mime_type: metadata.mime_type || undefined,
                is_dir: false,
                created: new Date(metadata.created_at).toISOString(),
                modified: new Date(metadata.updated_at).toISOString(),
                original_client_socket_id: null,
                thumbnail: metadata.thumbnail || undefined // Include thumbnail if available
              });
            }
            
            logger.info('[Batch] File uploaded successfully', { path: metadata.path, dirpath });
          } catch (error) {
            logger.error('[Batch] Error uploading file:', error);
            results.push({
              success: false,
              error: error instanceof Error ? error.message : 'Unknown error',
              filename: file.originalname || file.name
            });
          }
        }
      } else if ((req as any).file) {
        // Single file upload (not array)
        const file = (req as any).file;
        try {
          let destPath = formData.path || formData.dest_path || req.query.path as string;
          if (!destPath) {
            results.push({
              success: false,
              error: 'Missing destination path',
              filename: file.originalname || file.name
            });
          } else {
            // Resolve path (handle ~ and relative paths)
            if (destPath.startsWith('~')) {
              destPath = destPath.replace('~', `/${req.user.wallet_address}`);
            } else if (!destPath.startsWith('/')) {
              destPath = `/${req.user.wallet_address}/${destPath}`;
            }
            
            const fileName = file.originalname || file.name || 'untitled';
            const filePath = destPath.endsWith('/') 
              ? `${destPath}${fileName}`
              : `${destPath}/${fileName}`;
            
            logger.info('[Batch] Uploading single file', {
              originalDest: formData.path || formData.dest_path || req.query.path,
              resolvedDest: destPath,
              fileName,
              filePath
            });
            
            const singleFileContent = file.buffer || file.data;
            const singleOnDisk = !singleFileContent && file.path;

            const metadata = singleOnDisk
              ? await filesystem.writeFileFromPath(
                  filePath,
                  file.path,
                  req.user.wallet_address,
                  { mimeType: file.mimetype || file.type }
                )
              : await filesystem.writeFile(
                  filePath,
                  singleFileContent,
                  req.user.wallet_address,
                  { mimeType: file.mimetype || file.type }
                );
            
            // Extract parent directory path (dirpath) - CRITICAL for frontend
            const pathParts = metadata.path.split('/').filter(p => p);
            pathParts.pop(); // Remove filename
            const dirpath = pathParts.length > 0 ? '/' + pathParts.join('/') : '/';
            
            const fileUid = `uuid-${metadata.path.replace(/\//g, '-')}`;
            
            results.push({
              success: true,
              path: metadata.path,
              result: {
                path: metadata.path,
                name: metadata.path.split('/').pop() || 'untitled',
                size: metadata.size,
                mime_type: metadata.mime_type
              }
            });
            
            // Broadcast item.added event (frontend listens for this, not file:changed)
            if (io) {
              broadcastItemAdded(io, req.user.wallet_address, {
                uid: fileUid,
                uuid: fileUid,
                name: metadata.path.split('/').pop() || 'untitled',
                path: metadata.path,
                dirpath: dirpath, // CRITICAL: Frontend uses this to find where to add the item
                size: metadata.size,
                type: metadata.mime_type || null,
                mime_type: metadata.mime_type || undefined,
                is_dir: false,
                created: new Date(metadata.created_at).toISOString(),
                modified: new Date(metadata.updated_at).toISOString(),
                original_client_socket_id: null,
                thumbnail: metadata.thumbnail || undefined // Include thumbnail if available
              });
            }
          }
        } catch (error) {
          logger.error('[Batch] Error uploading file:', {
            error: error instanceof Error ? error.message : 'Unknown error',
            errorCode: (error as any)?.code,
            errorStack: error instanceof Error ? error.stack : undefined,
            filename: file.originalname || file.name
          });
          results.push({
            success: false,
            error: error instanceof Error ? error.message : 'Unknown error',
            filename: file.originalname || file.name
          });
        }
      } else {
        logger.warn('[Batch] Multipart request but no files found in req.files or req.file');
        // Try to parse from body if multer didn't process it
        // This might happen if multer middleware wasn't applied
        results.push({
          success: false,
          error: 'No files found in multipart request. Multer middleware may not be configured.'
        });
      }
    } else {
      // JSON batch operations
      const body = req.body as any;
      
      logger.info('[Batch] Processing JSON batch operations', {
        hasOperations: !!body.operations,
        operationsCount: Array.isArray(body.operations) ? body.operations.length : 0
      });
      
      if (body && Array.isArray(body.operations)) {
        for (const op of body.operations) {
          try {
            if (op.type === 'write' && op.path && op.content) {
              const content = typeof op.content === 'string' 
                ? Buffer.from(op.content, op.encoding || 'utf8')
                : Buffer.from(op.content);
              
              const metadata = await filesystem.writeFile(
                op.path,
                content,
                req.user.wallet_address,
                {
                  mimeType: op.mimeType
                }
              );
              
              results.push({
                success: true,
                path: metadata.path,
                result: metadata
              });
              
              if (io) {
                broadcastFileChange(io, {
                  path: metadata.path,
                  wallet_address: req.user.wallet_address,
                  action: 'created',
                  metadata: {
                    size: metadata.size,
                    mime_type: metadata.mime_type || undefined,
                    is_dir: false
                  }
                });
              }
            } else {
              results.push({
                success: false,
                error: `Unknown operation type: ${op.type || 'missing'}`
              });
            }
          } catch (error) {
            results.push({
              success: false,
              error: error instanceof Error ? error.message : 'Unknown error',
              path: op.path
            });
          }
        }
      } else {
        logger.warn('[Batch] JSON request but no operations array found');
        // Empty batch - return empty results
      }
    }
    
    logger.info('[Batch] Batch operation completed', {
      resultsCount: results.length,
      successCount: results.filter(r => r.success).length,
      failureCount: results.filter(r => !r.success).length
    });
    
    res.json({ results });
  } catch (error) {
    logger.error('[Batch] Error processing batch operations:', error);
    res.status(500).json({
      error: 'Failed to process batch operations',
      message: error instanceof Error ? error.message : 'Unknown error'
    });
  }
}

/**
 * Cache timestamp endpoint (used by Puter SDK)
 * GET /cache/last-change-timestamp
 * No auth required - SDK calls this during initialization
 */
export function handleCacheTimestamp(req: Request, res: Response): void {
  // Return current timestamp (SDK expects this format)
  res.json({ timestamp: Date.now() });
}

/**
 * Compute effective storage limit (bytes) from db setting, config, or auto-detect.
 * Shared by /api/stats and /api/storage/usage so both show the same limit.
 */
export function getEffectiveStorageLimit(db: { getSetting(name: string): string | undefined } | null | undefined): number {
  const dbLimit = db?.getSetting('storage_limit');
  const configLimit = dbLimit || (global as any).pc2Config?.resources?.storage?.limit;

  if (configLimit === 'auto' || !configLimit) {
    try {
      const fs = require('fs');
      const dataPath = process.cwd();
      const stats = fs.statfsSync ? fs.statfsSync(dataPath) : null;
      if (stats) {
        const totalDiskBytes = stats.blocks * stats.bsize;
        const reserveBytes = 10 * 1024 * 1024 * 1024; // Reserve 10GB free
        let limit = Math.min(
          Math.floor((totalDiskBytes - reserveBytes) * 0.8),
          500 * 1024 * 1024 * 1024 // Max 500GB
        );
        return Math.max(limit, 1 * 1024 * 1024 * 1024);
      }
      return 100 * 1024 * 1024 * 1024; // 100GB default
    } catch {
      return 100 * 1024 * 1024 * 1024;
    }
  }
  if (configLimit === 'unlimited') {
    return Number.MAX_SAFE_INTEGER;
  }
  if (typeof configLimit === 'string') {
    const match = configLimit.match(/^(\d+)(GB|MB|TB)$/i);
    if (match) {
      const value = parseInt(match[1], 10);
      const unit = match[2].toUpperCase();
      const multipliers: Record<string, number> = { 'MB': 1024 * 1024, 'GB': 1024 * 1024 * 1024, 'TB': 1024 * 1024 * 1024 * 1024 };
      return value * (multipliers[unit] || 1024 * 1024 * 1024);
    }
    return 100 * 1024 * 1024 * 1024;
  }
  return configLimit as number;
}

/**
 * Get storage statistics
 * GET /api/stats
 * Returns storage usage, file counts, etc.
 */
export function handleStats(req: AuthenticatedRequest, res: Response): void {
  const db = (req.app.locals.db as any);
  const filesystem = (req.app.locals.filesystem as any);

  if (!req.user) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  try {
    const walletAddress = req.user.wallet_address;
    const storageLimit = getEffectiveStorageLimit(db);

    // If database doesn't exist, return empty stats
    if (!db) {
      res.json({
        storageUsed: 0,
        storageLimit: storageLimit,
        storage: {
          used: 0,
          limit: storageLimit,
          available: storageLimit
        },
        filesCount: 0,
        files: 0,
        encryptedCount: 0,
        directories: 0
      });
      return;
    }
    
    // Count files and directories from database
    // Query all files for this user (using root path to get all files)
    const allFiles = db.listFiles('/', walletAddress);
    
    let totalSize = 0;
    let fileCount = 0;
    let directoryCount = 0;
    
    for (const file of allFiles) {
      if (file.is_dir) {
        directoryCount++;
      } else {
        fileCount++;
        totalSize += file.size || 0;
      }
    }
    
    // Return in format expected by Settings page
    res.json({
      storageUsed: totalSize,
      storageLimit: storageLimit,
      storage: {
        used: totalSize,
        limit: storageLimit,
        available: storageLimit - totalSize
      },
      filesCount: fileCount,
      files: fileCount,
      encryptedCount: 0, // Encryption not implemented yet
      directories: directoryCount
    });
  } catch (error) {
    log.error('[handleStats] Error:', error);
    res.status(500).json({
      error: 'Failed to get storage stats',
      message: error instanceof Error ? error.message : 'Unknown error'
    });
  }
}


